export const DEFAULT_STEERING_LEASE_TTL_MS = 5 * 60 * 1000;

export type SteeringCompletionStatus =
  | "pending"
  | "suspended"
  | "in_progress"
  | "delivered"
  | "discarded"
  | "failed";

export interface SteeringCompletionResult {
  prompt?: string;
  mergedPrompt?: string;
  output?: string;
  [key: string]: unknown;
}

export interface SteeringCompletion {
  id: string;
  requesterSessionKey: string;
  status: SteeringCompletionStatus;
  prompt?: string;
  result?: SteeringCompletionResult | string;
  steeringLeaseId?: string;
  leasedAt?: number;
  createdAt?: number;
  updatedAt?: number;
  [key: string]: unknown;
}

export interface SteeringLeaseRequest {
  requesterSessionKey: string;
  now?: number;
  leaseId?: string;
  leaseTtlMs?: number;
}

export interface SteeringLease {
  id: string;
  completionId: string;
  requesterSessionKey: string;
  steeringLeaseId: string;
  leasedAt: number;
  expiresAt: number;
  prompt: string;
  completion: SteeringCompletion;
}

export interface SteeringLeaseResult {
  leased: boolean;
  lease?: SteeringLease;
  steeringLeaseId?: string;
  prompt?: string;
  completion?: SteeringCompletion;
  reason?: "empty" | "session_mismatch" | "terminal" | "already_leased";
}

export interface SteeringAckRequest {
  steeringLeaseId: string;
  completionId?: string;
  requesterSessionKey?: string;
  now?: number;
}

export interface SteeringReleaseRequest {
  steeringLeaseId: string;
  completionId?: string;
  requesterSessionKey?: string;
  now?: number;
}

export interface SteeringQueueState {
  completions: SteeringCompletion[];
}

export interface AgentSteeringQueueOptions {
  state?: SteeringQueueState | SteeringCompletion[];
  leaseTtlMs?: number;
  idFactory?: () => string;
}

interface PendingLease {
  id: string;
  completionId: string;
  requesterSessionKey: string;
  steeringLeaseId: string;
  leasedAt: number;
  expiresAt: number;
}

const TERMINAL_STATUSES = new Set<SteeringCompletionStatus>([
  "delivered",
  "discarded",
  "failed",
]);

function completionPrompt(completion: SteeringCompletion): string {
  if (typeof completion.result === "string") {
    return completion.result;
  }
  if (completion.result?.mergedPrompt !== undefined) {
    return completion.result.mergedPrompt;
  }
  if (completion.result?.prompt !== undefined) {
    return completion.result.prompt;
  }
  if (completion.result?.output !== undefined) {
    return completion.result.output;
  }
  return completion.prompt ?? "";
}

function normalizeState(
  state?: SteeringQueueState | SteeringCompletion[],
): SteeringCompletion[] {
  const completions = Array.isArray(state) ? state : state?.completions;
  return (completions ?? []).map((completion) => ({ ...completion }));
}

/**
 * In-memory, lease-aware queue for completed agent runs.  The queue deliberately
 * keeps ownership in the completion record so it can be serialized and restored
 * after a runtime restart.
 */
export class AgentSteeringQueue {
  private completions = new Map<string, SteeringCompletion>();
  private leases = new Map<string, PendingLease>();
  private readonly leaseTtlMs: number;
  private readonly idFactory: () => string;

  constructor(options: AgentSteeringQueueOptions = {}) {
    this.leaseTtlMs = options.leaseTtlMs ?? DEFAULT_STEERING_LEASE_TTL_MS;
    this.idFactory = options.idFactory ?? (() => globalThis.crypto.randomUUID());
    for (const completion of normalizeState(options.state)) {
      this.completions.set(completion.id, completion);
      if (
        completion.status === "in_progress" &&
        completion.steeringLeaseId !== undefined &&
        completion.leasedAt !== undefined
      ) {
        this.leases.set(completion.steeringLeaseId, {
          id: completion.id,
          completionId: completion.id,
          requesterSessionKey: completion.requesterSessionKey,
          steeringLeaseId: completion.steeringLeaseId,
          leasedAt: completion.leasedAt,
          expiresAt: completion.leasedAt + this.leaseTtlMs,
        });
      }
    }
  }

  enqueue(input: SteeringCompletion): SteeringCompletion {
    const completion: SteeringCompletion = {
      ...input,
      status: input.status ?? "pending",
    };
    this.completions.set(completion.id, completion);
    return { ...completion };
  }

  add(input: SteeringCompletion): SteeringCompletion {
    return this.enqueue(input);
  }

  lease(request: SteeringLeaseRequest): SteeringLeaseResult {
    const now = request.now ?? Date.now();
    const ttl = request.leaseTtlMs ?? this.leaseTtlMs;
    const candidates = [...this.completions.values()]
      .filter((completion) => completion.requesterSessionKey === request.requesterSessionKey)
      .filter(
        (completion) =>
          completion.status === "pending" || completion.status === "suspended",
      )
      .sort((a, b) => (a.createdAt ?? 0) - (b.createdAt ?? 0));

    if (candidates.length === 0) {
      const hasSessionItem = [...this.completions.values()].some(
        (completion) => completion.requesterSessionKey === request.requesterSessionKey,
      );
      const hasInProgress = [...this.completions.values()].some(
        (completion) =>
          completion.requesterSessionKey === request.requesterSessionKey &&
          completion.status === "in_progress",
      );
      return {
        leased: false,
        reason: hasSessionItem ? (hasInProgress ? "already_leased" : "terminal") : "session_mismatch",
      };
    }

    const completion = candidates[0];
    const leaseId = request.leaseId ?? this.idFactory();
    const prompt = completionPrompt(completion);
    completion.status = "in_progress";
    completion.steeringLeaseId = leaseId;
    completion.leasedAt = now;
    completion.updatedAt = now;

    const lease: PendingLease = {
      id: completion.id,
      completionId: completion.id,
      requesterSessionKey: completion.requesterSessionKey,
      steeringLeaseId: leaseId,
      leasedAt: now,
      expiresAt: now + ttl,
    };
    this.leases.set(leaseId, lease);

    return {
      leased: true,
      lease: {
        ...lease,
        prompt,
        completion: { ...completion },
      },
      steeringLeaseId: leaseId,
      prompt,
      completion: { ...completion },
    };
  }

  leaseCompletion(request: SteeringLeaseRequest): SteeringLeaseResult {
    return this.lease(request);
  }

  ack(request: SteeringAckRequest): boolean {
    const lease = this.leases.get(request.steeringLeaseId);
    if (!lease) {
      return false;
    }
    const completion = this.completions.get(lease.completionId);
    if (!completion || completion.status !== "in_progress") {
      return false;
    }
    if (
      completion.steeringLeaseId !== request.steeringLeaseId ||
      (request.completionId !== undefined && request.completionId !== completion.id) ||
      (request.requesterSessionKey !== undefined &&
        request.requesterSessionKey !== completion.requesterSessionKey)
    ) {
      return false;
    }

    completion.status = "delivered";
    completion.updatedAt = request.now ?? Date.now();
    this.leases.delete(request.steeringLeaseId);
    return true;
  }

  acknowledge(request: SteeringAckRequest): boolean {
    return this.ack(request);
  }

  ackCompletion(request: SteeringAckRequest): boolean {
    return this.ack(request);
  }

  release(request: SteeringReleaseRequest): boolean {
    const lease = this.leases.get(request.steeringLeaseId);
    if (!lease) {
      return false;
    }
    const completion = this.completions.get(lease.completionId);
    if (!completion || completion.status !== "in_progress") {
      return false;
    }
    if (
      completion.steeringLeaseId !== request.steeringLeaseId ||
      (request.completionId !== undefined && request.completionId !== completion.id) ||
      (request.requesterSessionKey !== undefined &&
        request.requesterSessionKey !== completion.requesterSessionKey)
    ) {
      return false;
    }

    const now = request.now ?? Date.now();
    completion.status = "pending";
    delete completion.steeringLeaseId;
    delete completion.leasedAt;
    completion.updatedAt = now;
    this.leases.delete(request.steeringLeaseId);
    return true;
  }

  releaseCompletion(request: SteeringReleaseRequest): boolean {
    return this.release(request);
  }

  cancel(completionId: string, now = Date.now()): boolean {
    const completion = this.completions.get(completionId);
    if (!completion || TERMINAL_STATUSES.has(completion.status)) {
      return false;
    }
    completion.status = "discarded";
    completion.updatedAt = now;
    if (completion.steeringLeaseId !== undefined) {
      this.leases.delete(completion.steeringLeaseId);
    }
    delete completion.steeringLeaseId;
    delete completion.leasedAt;
    return true;
  }

  discard(completionId: string, now = Date.now()): boolean {
    return this.cancel(completionId, now);
  }

  fail(completionId: string, now = Date.now()): boolean {
    const completion = this.completions.get(completionId);
    if (!completion || TERMINAL_STATUSES.has(completion.status)) {
      return false;
    }
    completion.status = "failed";
    completion.updatedAt = now;
    if (completion.steeringLeaseId !== undefined) {
      this.leases.delete(completion.steeringLeaseId);
    }
    delete completion.steeringLeaseId;
    delete completion.leasedAt;
    return true;
  }

  pending(requesterSessionKey: string): SteeringCompletion[] {
    return [...this.completions.values()]
      .filter(
        (completion) =>
          completion.requesterSessionKey === requesterSessionKey &&
          (completion.status === "pending" || completion.status === "suspended"),
      )
      .map((completion) => ({ ...completion }));
  }

  listPending(requesterSessionKey: string): SteeringCompletion[] {
    return this.pending(requesterSessionKey);
  }

  get(completionId: string): SteeringCompletion | undefined {
    const completion = this.completions.get(completionId);
    return completion === undefined ? undefined : { ...completion };
  }

  snapshot(): SteeringQueueState {
    return {
      completions: [...this.completions.values()].map((completion) => ({
        ...completion,
      })),
    };
  }

  toJSON(): SteeringQueueState {
    return this.snapshot();
  }
}

let defaultQueue: AgentSteeringQueue | undefined;

function getDefaultQueue(): AgentSteeringQueue {
  defaultQueue ??= new AgentSteeringQueue();
  return defaultQueue;
}

export function enqueueSteeringCompletion(
  completion: SteeringCompletion,
): SteeringCompletion {
  return getDefaultQueue().enqueue(completion);
}

export function leaseSteeringCompletion(
  request: SteeringLeaseRequest,
): SteeringLeaseResult {
  return getDefaultQueue().lease(request);
}

export function leaseSteering(
  request: SteeringLeaseRequest,
): SteeringLeaseResult {
  return getDefaultQueue().lease(request);
}

export function ackSteeringCompletion(request: SteeringAckRequest): boolean {
  return getDefaultQueue().ack(request);
}

export function ackSteering(request: SteeringAckRequest): boolean {
  return getDefaultQueue().ack(request);
}

export function releaseSteeringCompletion(request: SteeringReleaseRequest): boolean {
  return getDefaultQueue().release(request);
}

export function releaseSteering(request: SteeringReleaseRequest): boolean {
  return getDefaultQueue().release(request);
}

export function cancelSteeringCompletion(
  completionId: string,
  now = Date.now(),
): boolean {
  return getDefaultQueue().cancel(completionId, now);
}

export function getPendingSteeringCompletions(
  requesterSessionKey: string,
): SteeringCompletion[] {
  return getDefaultQueue().pending(requesterSessionKey);
}

export function resetDefaultSteeringQueue(
  state?: SteeringQueueState | SteeringCompletion[],
): AgentSteeringQueue {
  defaultQueue = new AgentSteeringQueue({ state });
  return defaultQueue;
}

